findings.codeql_raw_query:
/**
 * @name Potential SQL injection in raw SQL execution
 * @description Tainted remote input flowing into raw SQL execution
 * @kind problem
 * @problem.severity error
 * @id py/django-sqli
 * @tags security
 *        external/cwe/cwe-089
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources

module SqliConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) { source instanceof RemoteFlowSource }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      call.getFunction().(DataFlow::AttrRead).getAttributeName() = "execute" and
      sink = call.getArg(0)
    )
  }

  predicate isAdditionalFlowStep(DataFlow::Node a, DataFlow::Node b) {
    exists(DataFlow::CallCfgNode c |
      c.getFunction().(DataFlow::AttrRead).getAttributeName() = ["format", "join"] and
      exists(int i | a = c.getArg(i)) and
      b = c
    )
  }
}

module SqliFlow = TaintTracking::Global<SqliConfig>;

from DataFlow::Node source, DataFlow::Node sink
where SqliFlow::flow(source, sink)
select sink, "Raw SQL execution of $@ may allow SQL injection.", source, "user input"
